// Split feed-manager article array into individual n8n items
// feed-manager already deduplicates within this batch by URL hash
const articles = Array.isArray($input.item.json) ? $input.item.json : [];
const now = new Date().toISOString();

return articles.map(a => ({
  id:          a.id,
  title:       a.title || 'Untitled',
  url:         a.url   || '',
  summary:     a.summary || '',
  pubDate:     a.published || now,
  source:      a.source_name || 'unknown',
  category:    a.source_category || 'general',
  processedAt: now
}));

