// Parse Claude's JSON scoring response and merge with article data
const article = $('Split Articles').item.json;
const rawResponse = $input.item.json.text || $input.item.json.content || '';

let scoring;
try {
  const cleaned = rawResponse.replace(/```json|```/g, '').trim();
  scoring = JSON.parse(cleaned);
} catch(e) {
  scoring = { score: 0, reason: 'parse error: ' + e.message, tags: [], tldr: '' };
}

return {
  ...article,
  score:  typeof scoring.score === 'number' ? scoring.score : 0,
  reason: scoring.reason || '',
  tags:   (scoring.tags  || []).join(', '),
  tldr:   scoring.tldr   || ''
};

// Route article to a tier based on configurable env var thresholds.
// Centralising the threshold logic here avoids duplicating it across IF nodes
// and makes it trivial to change SCORE_PUBLISH_MIN / SCORE_REVIEW_MIN in .env.
const score      = $json.score;
const publishMin = parseInt($env.SCORE_PUBLISH_MIN) || 7;
const reviewMin  = parseInt($env.SCORE_REVIEW_MIN)  || 4;

const tier = score >= publishMin ? 'published'
           : score >= reviewMin  ? 'review'
           : 'archived';

return { ...$json, tier };

