// Merge article metadata with generated content analysis
const article = $('Route Article').item.json;
const rawResp  = $input.item.json.text || $input.item.json.content || '';

let content;
try {
  const cleaned = rawResp.replace(/```json|```/g, '').trim();
  content = JSON.parse(cleaned);
} catch(e) {
  content = { headline: article.title, analysis: '', so_what: '', action_items: [] };
}

return {
  title:        article.title,
  headline:     content.headline     || article.title,
  url:          article.url,
  source:       article.source,
  category:     article.category,
  pubDate:      article.pubDate,
  score:        article.score,
  tags:         article.tags,
  tldr:         article.tldr,
  analysis:     content.analysis     || '',
  so_what:      content.so_what      || '',
  action_items: (content.action_items || []).join(' | '),
  processedAt:  article.processedAt
};
